package dicom

import (
	"math"
	"testing"
)

// Test vectors generated by running the Python roimath.py math with
// numpy (points.dot(make_transform(iop, ipp))).
func TestMakeTransformMatchesNumpy(t *testing.T) {
	iop := []float64{-8.3346015e-2, 9.9652019e-1, -9.7995078e-4,
		1.2180652e-4, -9.7318472e-4, -9.9999952e-1}
	ipp := []float64{-3.59993e-1, -223.741, 261.634}

	points := [][4]float64{
		{-14.611, -53.268, 88.894, 1},
		{-14.622, -53.135, -14.8, 1},
		{-14.8, -51.007, -51.007, 1},
		{-14.811, -50.874, 88.892, 1},
	}
	want := [][2]float64{
		{1.7123682769079431e+02, 1.7257227950045825e+02},
		{1.7147189669841063e+02, 2.7626609895389879e+02},
		{1.7364280833129209e+02, 3.1247098895589409e+02},
		{1.7363916818855586e+02, 1.7257192533397458e+02},
	}

	xform := MakeTransform(iop, ipp)
	for i, p := range points {
		got := applyRow(p, xform)
		for j := range 2 {
			if math.Abs(got[j]-want[i][j]) > 1e-9 {
				t.Errorf("point %d coord %d: got %v want %v", i, j, got[j], want[i][j])
			}
		}
	}
}

func TestTransformContourMatchesNumpy(t *testing.T) {
	iop := []float64{-8.3346015e-2, 9.9652019e-1, -9.7995078e-4,
		1.2180652e-4, -9.7318472e-4, -9.9999952e-1}
	ipp := []float64{-3.59993e-1, -223.741, 261.634}
	points := [][4]float64{
		{-14.611, -53.268, 88.894, 1},
		{-14.622, -53.135, -14.8, 1},
		{-14.8, -51.007, -51.007, 1},
		{-14.811, -50.874, 88.892, 1},
	}
	// numpy: (gpoints / [0.5, 0.5]).astype(int)
	want := [][2]int64{{342, 345}, {342, 552}, {347, 624}, {347, 345}}

	got := TransformContour(points, MakeTransform(iop, ipp), []float64{0.5, 0.5})
	for i := range want {
		if got[i] != want[i] {
			t.Errorf("point %d: got %v want %v", i, got[i], want[i])
		}
	}
}

func TestConsistentSortsByProjectedPosition(t *testing.T) {
	mk := func(id int64, z float64) ImageFile {
		return ImageFile{
			FileID:      id,
			Orientation: []float64{1, 0, 0, 0, 1, 0},
			Position:    []float64{0, 0, z},
		}
	}
	files := []ImageFile{mk(1, 5), mk(2, -3), mk(3, 1)}
	sorted, volumetric := Consistent(files)
	if !volumetric {
		t.Fatal("expected volumetric=true")
	}
	if sorted[0].FileID != 2 || sorted[1].FileID != 3 || sorted[2].FileID != 1 {
		t.Errorf("bad sort order: %v %v %v",
			sorted[0].FileID, sorted[1].FileID, sorted[2].FileID)
	}
}

func TestConsistentEdgeCases(t *testing.T) {
	if _, v := Consistent(nil); v {
		t.Error("empty list should be non-volumetric")
	}
	oneSlice := []ImageFile{{Orientation: []float64{1, 0, 0, 0, 1, 0}, Position: []float64{0, 0, 0}}}
	if _, v := Consistent(oneSlice); v {
		t.Error("single slice should be non-volumetric")
	}
	missingGeom := []ImageFile{
		{Orientation: []float64{1, 0, 0, 0, 1, 0}, Position: []float64{0, 0, 0}},
		{Orientation: []float64{}, Position: []float64{}},
	}
	if _, v := Consistent(missingGeom); v {
		t.Error("missing geometry should be non-volumetric")
	}
}

func TestParseContourPoints(t *testing.T) {
	pts, err := ParseContourPoints(`1\2\3\4\5\6`)
	if err != nil {
		t.Fatal(err)
	}
	if len(pts) != 2 || pts[0] != [4]float64{1, 2, 3, 1} || pts[1] != [4]float64{4, 5, 6, 1} {
		t.Errorf("unexpected points: %v", pts)
	}
	if _, err := ParseContourPoints(`1\2`); err == nil {
		t.Error("expected error for non-3d contour")
	}
}

func TestFormatColor(t *testing.T) {
	if got := FormatColor(`255\0\128`); got != [3]int64{255, 0, 128} {
		t.Errorf("got %v", got)
	}
	if got := FormatColor(""); got != [3]int64{0, 0, 0} {
		t.Errorf("empty color: got %v", got)
	}
	if got := FormatColor(`1\2`); got != [3]int64{0, 0, 0} {
		t.Errorf("short color: got %v", got)
	}
}
